// Message catalogue v1 for the highlight feature (architecture.md D6 "Message catalogue").
import type { ColorName, HighlightRecord, TextAnchor } from '../../../core/model/index.ts'
import type { LogRecord } from '../../../core/log/types.ts'
import type { OutboxItem } from '../../../core/db/read.ts'
import type { SyncStatus } from '../../../core/sync/protocol.ts'

export interface PageState {
  canonicalUrl: string
  siteKey: string
  enabled: boolean
  signedIn: boolean
  highlights: HighlightRecord[]
}

export interface CreateHighlightReq {
  /** crypto.randomUUID() generated by the caller. */
  id: string
  url: string
  text: string
  color: ColorName
  comment: string | null
  anchor: TextAnchor | null
  pageTitle: string | null
  favicon: string | null
}

export interface HighlightPatch {
  color?: ColorName
  comment?: string | null
}

export interface DebugDump {
  /** Every highlight id, including soft-deleted ones. */
  ids: string[]
  outbox: OutboxItem[]
  syncStatus: SyncStatus
  logs: LogRecord[]
}

export type HighlightRequests = {
  'page/getState': { req: { url: string }; res: PageState }
  'highlight/create': { req: CreateHighlightReq; res: HighlightRecord }
  'highlight/update': { req: { id: string; patch: HighlightPatch }; res: HighlightRecord }
  'highlight/delete': { req: { id: string }; res: HighlightRecord }
  'highlight/restore': { req: { id: string }; res: HighlightRecord }
}

/** Manual per-site override (D8): enabled=true writes 'on', false writes 'off' (rule in background/site-state.ts). */
export type SiteRequests = {
  'site/setEnabled': { req: { siteKey: string; enabled: boolean }; res: void }
}

/** Anchor report (content -> SW) after the lost window of a page load (architecture.md Q54). */
export interface AnchorReport {
  canonicalUrl: string
  found: string[]
  lost: string[]
}

/** Anchoring and jump requests (Q54, Q55, FR13, FR22). */
export type AnchorRequests = {
  'anchor/report': { req: AnchorReport; res: void }
  /** flashed: the highlight was scrolled to and flashed; lost: it could not be shown on its page. */
  'nav/jumpTo': { req: { id: string }; res: { result: 'flashed' | 'lost' } }
}

/** Registered only in non-production builds or the debug page. */
export type DebugRequests = {
  'debug/dump': { req: void; res: DebugDump }
}

/** A manual site switch (site/setEnabled) changed a site's enabled state (D8, FR18). */
export interface SiteChanged {
  siteKey: string
  enabled: boolean
}

export type HighlightEvents = {
  'db/changed': { ids: string[] }
  /** Side panel: re-read the site state of the active tab. */
  'site/changed': SiteChanged
}

/**
 * page/sync payload (SW -> content). Carries only the records affected by one commit for one page:
 * live ones in upserts, soft-deleted ones as ids in removes (architecture.md D6 "Cross-tab broadcast").
 */
export interface PageSync {
  canonicalUrl: string
  upserts: HighlightRecord[]
  removes: string[]
  enabled: boolean
  signedIn: boolean
}

/**
 * Requests the service worker sends to one tab's content script (chrome.tabs.sendMessage).
 * page/triggerHighlight comes from the shortcut and the context menu; the SW has already turned the
 * site on, and content creates a highlight from the current selection.
 */
export type PageRequests = {
  'page/triggerHighlight': { req: { color: ColorName }; res: HighlightRecord }
  /** Scrolls to and flashes one highlight, waiting up to the lost window for it to render. */
  'page/flash': { req: { id: string }; res: { found: boolean } }
  /**
   * Check from the side panel whether this tab can highlight. Chrome injects content scripts into
   * the PDF viewer's wrapper document, so the script answers there too and reports supported: false.
   * A tab with no content script at all fails the request (no receiver).
   */
  'page/ping': { req: Record<string, never>; res: { supported: boolean } }
}

/** Events the service worker sends to content scripts with chrome.tabs.sendMessage. */
export type PageEvents = {
  'page/sync': PageSync
  /** Local data was wiped (sign-out or first sign-in): remove every rendered highlight. */
  'page/clear': Record<string, never>
  /** The site was switched on or off: render or remove this page's highlights (FR18). */
  'site/changed': SiteChanged
}
